from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 16
#define UNROLL_FACTOR 4

__global__ void matmul_kernel_unrolled(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float sum = 0.0f;
    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        if (row < N && (t * TILE_DIM + tx) < N) {
            As[ty][tx] = A[row * N + t * TILE_DIM + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        if ((t * TILE_DIM + ty) < N && col < N) {
            Bs[ty][tx] = B[(t * TILE_DIM + ty) * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }
        __syncthreads();

        for (int k = 0; k < TILE_DIM; k += UNROLL_FACTOR) {
            sum += As[ty][k] * Bs[k][tx];
            sum += As[ty][k+1] * Bs[k+1][tx];
            sum += As[ty][k+2] * Bs[k+2][tx];
            sum += As[ty][k+3] * Bs[k+3][tx];
        }
        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

