    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const dim3 blockSize(TILE_DIM, TILE_DIM);
    const dim3 gridSize((N + blockSize.x - 1) / blockSize.x, (N + blockSize.y - 1) / blockSize.y);

    matmul_kernel_unrolled<<<gridSize, blockSize>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
